<script setup lang="ts">
import {computed} from 'vue';
import AiBall from '../../../shared/components/AiBall.vue';
const props=withDefaults(defineProps<{phase?:string;preparing?:boolean;units?:Array<{title:string;objective:string}>;connectionError?:string}>(),{phase:'QUEUED',units:()=>[]});
const stages=[{id:'QUEUED',label:'等待开始'},{id:'RETRIEVING',label:'查阅课程资料'},{id:'PLANNING',label:'编排学习路线'},{id:'VALIDATING',label:'检查大纲'}];
const preparationLabels:Record<string,string>={PREPARING_RESOURCES:'正在整理首段课程材料',GENERATING_CONTENT:'正在编写首段讲解',PUBLISHING:'正在发布通过检查的首段讲解'};
const label=computed(()=>props.preparing?(preparationLabels[props.phase]??'正在准备首段讲解'):stages.find(stage=>stage.id===props.phase)?.label??'正在准备学习内容');
const index=computed(()=>stages.findIndex(stage=>stage.id===props.phase));
</script>
<template>
 <section class="generation-feedback" aria-label="课堂生成进度" :aria-busy="true">
  <div class="generation-heading"><div class="generation-mascot"><AiBall size="message" :follow-pointer="false" expressive/></div><div><p class="generation-eyebrow">{{preparing?'即将开始学习':'正在为你规划'}}</p><h3 role="status" aria-live="polite">{{label}}<span class="generation-dots" aria-hidden="true">…</span></h3><p>{{preparing?'通过检查后会自动进入课堂，后续内容将在阅读时继续准备。':'知识点会逐项出现，整份大纲通过检查后即可审阅。'}}</p></div></div>
  <ol v-if="!preparing" class="generation-phases" aria-label="生成阶段"><li v-for="(stage,i) in stages" :key="stage.id" :class="{current:i===index,done:i<index}" :aria-current="i===index?'step':undefined"><span aria-hidden="true">{{i<index?'✓':i+1}}</span>{{stage.label}}</li></ol>
  <TransitionGroup v-if="units.length" tag="ol" name="outline-preview" class="generation-preview" aria-label="正在生成的知识点预览"><li v-for="(unit,i) in units" :key="i"><span class="preview-number">{{String(i+1).padStart(2,'0')}}</span><div><h4>{{unit.title}}</h4><p>{{unit.objective}}</p></div><span class="preview-label">预览</span></li></TransitionGroup>
  <div v-else class="generation-skeleton" aria-hidden="true"><span/><span/><span/></div>
  <p v-if="connectionError" class="generation-reconnecting" role="status">连接暂时中断，正在恢复已有进度。</p>
 </section>
</template>
